from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import multitask, run_task, wait

# Set up.
prime_hub = PrimeHub()
Left = Motor(Port.A, Direction.COUNTERCLOCKWISE)
Right = Motor(Port.E, Direction.CLOCKWISE)
drive_base = DriveBase(Left, Right, 66, 135)
Flipper = Motor(Port.C, Direction.COUNTERCLOCKWISE)
WheelDiameter_mm = 0
WheelCircumference_cm = 0
RotationSpeed = 0
RotateDirection = 0
K = 0
Error = 0

async def Move_2_________cm_at_____Move_speed_at_____Heading(ForwardOrBackward, Distance_cm, MoveSpeed, Heading):
    await wait(0)
    await Move________at_____at____(ForwardOrBackward, (Distance_cm / WheelCircumference_cm) * 360, MoveSpeed, Heading)

async def Move________at_____at____(ForwardOrBackward, RelativePosition, MoveSpeed, Heading):
    global K, RotateDirection, Error
    await wait(0)
    K = 0.5
    if 'forward' in ForwardOrBackward:
        RotateDirection = 1
    else:
        RotateDirection = -1
    while not (abs(0) > abs(RelativePosition) or abs(0) == abs(RelativePosition)):
        await wait(0)
        Error = prime_hub.imu.heading() - Heading
        drive_base.drive((RotateDirection * MoveSpeed - Error * K) * 360, 0)
    drive_base.brake()
    await wait(2000)

